drop policy if exists staff_email_threads_staff on public.staff_email_threads;
create policy staff_email_threads_staff_select on public.staff_email_threads for select to authenticated using(company_id=private.current_company_id() and private.staff_email_allowed());
drop policy if exists staff_email_messages_staff on public.staff_email_messages;
create policy staff_email_messages_staff_select on public.staff_email_messages for select to authenticated using(company_id=private.current_company_id() and private.staff_email_allowed());
drop policy if exists staff_email_attachments_staff on public.staff_email_attachments;
create policy staff_email_attachments_staff_select on public.staff_email_attachments for select to authenticated using(company_id=private.current_company_id() and private.staff_email_allowed());
create or replace function public.staff_email_link_thread(p_thread uuid,p_client uuid default null,p_candidate uuid default null,p_job uuid default null) returns void language plpgsql security definer set search_path='' as $$ declare c uuid:=private.current_company_id(); begin if not private.staff_email_allowed() then raise exception 'Manager access required'; end if; if p_client is not null and not exists(select 1 from public.clients where id=p_client and company_id=c) then raise exception 'Client not found'; end if; if p_candidate is not null and not exists(select 1 from public.candidates where id=p_candidate and company_id=c) then raise exception 'Candidate not found'; end if; if p_job is not null and not exists(select 1 from public.jobs where id=p_job and company_id=c) then raise exception 'Vacancy not found'; end if; update public.staff_email_threads set client_id=p_client,candidate_id=p_candidate,job_id=p_job,updated_at=now() where id=p_thread and company_id=c; if not found then raise exception 'Thread not found'; end if; insert into public.staff_email_audit(company_id,actor_id,action,thread_id,metadata) values(c,auth.uid(),'link_thread',p_thread,jsonb_build_object('client_id',p_client,'candidate_id',p_candidate,'job_id',p_job)); end $$;
create or replace function public.staff_email_set_thread_state(p_thread uuid,p_read boolean default null,p_starred boolean default null,p_archived boolean default null) returns void language plpgsql security definer set search_path='' as $$ declare c uuid:=private.current_company_id(); begin if not private.staff_email_allowed() then raise exception 'Manager access required'; end if; update public.staff_email_threads set is_starred=coalesce(p_starred,is_starred),is_archived=coalesce(p_archived,is_archived),updated_at=now() where id=p_thread and company_id=c; if not found then raise exception 'Thread not found'; end if; if p_read is not null then update public.staff_email_messages set is_read=p_read where thread_id=p_thread and company_id=c and direction='inbound'; update public.staff_email_threads set unread_count=(select count(*) from public.staff_email_messages where thread_id=p_thread and direction='inbound' and not is_read) where id=p_thread and company_id=c; end if; insert into public.staff_email_audit(company_id,actor_id,action,thread_id,metadata) values(c,auth.uid(),'thread_state',p_thread,jsonb_build_object('read',p_read,'starred',p_starred,'archived',p_archived)); end $$;
revoke all on function public.staff_email_link_thread(uuid,uuid,uuid,uuid) from public,anon;grant execute on function public.staff_email_link_thread(uuid,uuid,uuid,uuid) to authenticated;
revoke all on function public.staff_email_set_thread_state(uuid,boolean,boolean,boolean) from public,anon;grant execute on function public.staff_email_set_thread_state(uuid,boolean,boolean,boolean) to authenticated;
